"""Regenerate Java SOS coefficients using the pinned SciPy design environment."""
from pathlib import Path
from scipy.signal import butter

ROOT = Path(__file__).resolve().parents[1]
CONFIGS = [(0.05, 35, 4), (0.1, 35, 4), (0.05, 30, 4), (0.1, 30, 2)]

def matrix(rows):
    return "new double[][]{" + ",".join("{" + ",".join(format(v, '.17g') for v in row) + "}" for row in rows) + "}"

def main():
    parts = ['package com.ecg.filter.butterworth;\nimport com.ecg.filter.adaptive.FilterConfig;\n',
             '/** Generated by scripts/generate_sos.py; SciPy butter, fs=250 Hz. Returns fresh arrays. */\n',
             'public final class SosCoefficients {\n private SosCoefficients() {}\n']
    for kind, index in [('high', 0), ('low', 1)]:
        parts.append(' public static double[][] '+kind+'(FilterConfig config) {\n switch(config) {\n')
        for name, spec in zip(['CONFIG_DEFAULT', 'CONFIG_BASELINE_HEAVY', 'CONFIG_MUSCLE_HEAVY', 'CONFIG_CONSERVATIVE'], CONFIGS):
            sos = butter(spec[2], spec[index], btype=kind+'pass', fs=250, output='sos')
            parts.append(' case '+name+': return '+matrix(sos)+';\n')
        parts.append(' default: throw new IllegalArgumentException("Unknown config");\n }\n }\n')
    parts.append('}\n')
    (ROOT/'src/main/java/com/ecg/filter/butterworth/SosCoefficients.java').write_text(''.join(parts), encoding='utf-8')

if __name__ == '__main__': main()
